import{_ as i,c as a,o as r,ag as n}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Leaving Service","description":"","frontmatter":{"title":"Leaving Service"},"headers":[],"relativePath":"general/leaving-service.md","filePath":"general/leaving-service.md","lastUpdated":null}'),t={name:"general/leaving-service.md"};function o(s,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="leaving-service" tabindex="-1">Leaving Service <a class="header-anchor" href="#leaving-service" aria-label="Permalink to &quot;Leaving Service&quot;">​</a></h1><h2 id="transitioning-out-of-the-military" tabindex="-1">Transitioning Out of the Military <a class="header-anchor" href="#transitioning-out-of-the-military" aria-label="Permalink to &quot;Transitioning Out of the Military&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Transitioning out of the military involves understanding retirement processes and adapting to civilian employment. This guide simplifies these steps with structured resources and advice.</p><h3 id="community-feedback" tabindex="-1">Community Feedback <a class="header-anchor" href="#community-feedback" aria-label="Permalink to &quot;Community Feedback&quot;">​</a></h3><h3 id="quotes" tabindex="-1">Quotes: <a class="header-anchor" href="#quotes" aria-label="Permalink to &quot;Quotes:&quot;">​</a></h3><blockquote><p>Don’t leave benefits you’ve earned on the table due to pride or neglect. Also remember your salary does not correlate with your worth. Especially if you’ve been in for a long time, your first job out may be more junior than your ego thinks is right, and your salary lower. But I got some excellent career advice in my early 20s when agonizing over a decision. A mentor said — this is not for the rest of your life. And yeah, of course no kidding. But you lose that perspective when the emotions are running high and you get insecure about things and you just want the security of the job offer. Many non-defense companies may feel intimidated. Leave your jargon, ego, profanity, and rank behind.</p></blockquote><h3 id="lessons-learned" tabindex="-1">Lessons Learned <a class="header-anchor" href="#lessons-learned" aria-label="Permalink to &quot;Lessons Learned&quot;">​</a></h3><p><a href="https://forum.irregularchat.com/t/practical-tips-for-service-to-civilian-career/4780?u=sac" target="_blank" rel="noreferrer">Practical Tips for transitioning to the Civilian Sector (2025)</a></p><h3 id="transition-assistance" tabindex="-1">Transition Assistance <a class="header-anchor" href="#transition-assistance" aria-label="Permalink to &quot;Transition Assistance&quot;">​</a></h3><h3 id="military-transition-assistance" tabindex="-1">Military Transition Assistance <a class="header-anchor" href="#military-transition-assistance" aria-label="Permalink to &quot;Military Transition Assistance&quot;">​</a></h3><ul><li><p><strong>Military Side</strong>: Numerous programs help with retirement or ETS (Expiration Term of Service) processes.</p></li><li><p><strong>Civilian Side</strong>: Insights from professionals outside the military are crucial, especially if entering an unrelated field.</p></li></ul><h3 id="transition-assistance-program-tap" tabindex="-1">Transition Assistance Program (TAP) <a class="header-anchor" href="#transition-assistance-program-tap" aria-label="Permalink to &quot;Transition Assistance Program (TAP)&quot;">​</a></h3><ul><li><p>Attend the “retiree” version of TAP if possible, focusing more on retiree benefits and less on the GI Bill.</p></li><li><p>“First thing is to take it seriously. Show up, pay attention, take notes. Interview prep is a skill. You are competing for a job.” — Engage fully in TAP and prepare thoroughly for what’s ahead.</p></li></ul><h3 id="professional-guidance" tabindex="-1">Professional Guidance <a class="header-anchor" href="#professional-guidance" aria-label="Permalink to &quot;Professional Guidance&quot;">​</a></h3><h3 id="classes-and-seminars" tabindex="-1">Classes and Seminars <a class="header-anchor" href="#classes-and-seminars" aria-label="Permalink to &quot;Classes and Seminars&quot;">​</a></h3><ul><li><p><strong>MilBridge Consulting</strong>: Noel McCall (704-904-4835, <a href="mailto:NoelMcCall@milbridgeconsult.com" target="_blank" rel="noreferrer">NoelMcCall@milbridgeconsult.com</a>) – Helps with resumes, LinkedIn profiles, and understanding the civilian recruitment process.</p></li><li><p><strong>JANUS 101/Donovan Bank Foundation</strong>: Paul (<a href="mailto:paul@donovanbank.org" target="_blank" rel="noreferrer">paul@donovanbank.org</a>), Drew (<a href="mailto:drew@donovanbank.org" target="_blank" rel="noreferrer">drew@donovanbank.org</a>) – Offers seminars for retiring ARSOF members on transitioning, life insurance choices, and more.</p></li><li><p><strong>The Honor Foundation</strong>: <a href="http://honor.org%7CHonor" target="_blank" rel="noreferrer">Foundation</a> – Specialized programs for transitioning members.</p></li></ul><h3 id="resume-writing" tabindex="-1">Resume Writing <a class="header-anchor" href="#resume-writing" aria-label="Permalink to &quot;Resume Writing&quot;">​</a></h3><h3 id="applying-with-recommendations" tabindex="-1">Applying with Recommendations <a class="header-anchor" href="#applying-with-recommendations" aria-label="Permalink to &quot;Applying with Recommendations&quot;">​</a></h3><ul><li><p><strong>Defense Related</strong>: Leverage military connections. Reach out to former colleagues in defense industries for referrals.</p></li><li><p><strong>Non-Defense Related</strong>: Expand your network and use professional networking sites to connect with industry leaders.</p></li></ul><h3 id="cold-applications" tabindex="-1">Cold Applications <a class="header-anchor" href="#cold-applications" aria-label="Permalink to &quot;Cold Applications&quot;">​</a></h3><ul><li><p><strong>Defense Related</strong>: Tailor your resume using industry-specific terminology, emphasizing skills like security clearances and leadership experience.</p></li><li><p><strong>Non-Defense Related</strong>: Highlight transferable skills and how military experience can translate to civilian success.</p></li></ul><h3 id="networking-and-skill-development" tabindex="-1">Networking and Skill Development <a class="header-anchor" href="#networking-and-skill-development" aria-label="Permalink to &quot;Networking and Skill Development&quot;">​</a></h3><ul><li><p>Utilize non-military experts for new perspectives and strategies.</p></li><li><p>&quot;Prepare answers to likely questions, rehearse. Many non-defense companies may feel intimidated. Leave your jargon, ego, profanity, and rank behind.&quot;</p></li><li><p>Mention projects you’ve started, even if not completed, to own your experience.</p></li></ul><h3 id="entrepreneurship-and-creative-ventures" tabindex="-1">Entrepreneurship and Creative Ventures <a class="header-anchor" href="#entrepreneurship-and-creative-ventures" aria-label="Permalink to &quot;Entrepreneurship and Creative Ventures&quot;">​</a></h3><ul><li>Consider starting your own business, engaging in side projects, or exploring creative ventures like online stores.</li></ul><h3 id="area-specific-tips" tabindex="-1">Area Specific Tips <a class="header-anchor" href="#area-specific-tips" aria-label="Permalink to &quot;Area Specific Tips&quot;">​</a></h3><ul><li>Look for local veteran resources and groups for tailored advice.</li></ul><h3 id="medboarding" tabindex="-1">MedBoarding <a class="header-anchor" href="#medboarding" aria-label="Permalink to &quot;MedBoarding&quot;">​</a></h3><ul><li><p><strong>Understanding Medboarding</strong>: Make sure to get assessed for potential disabilities and understand the benefits you’ve earned.</p></li><li><p>&quot;Most counties have a Veterans Service Officer (VSO) who can help navigate the VA and state benefits. If you can’t find them on your county or state veterans affairs page, try your local American Legion or VFW post.&quot;</p></li></ul><h3 id="state-considerations-for-disabled-veterans" tabindex="-1">State Considerations for Disabled Veterans <a class="header-anchor" href="#state-considerations-for-disabled-veterans" aria-label="Permalink to &quot;State Considerations for Disabled Veterans&quot;">​</a></h3><ul><li><p><strong>Texas</strong>: Generous property tax exemptions, no state income tax.</p></li><li><p><strong>Illinois</strong>: Offers property tax exemptions and income tax waivers for military retirement pay.</p></li><li><p><strong>Florida</strong>: Provides property tax benefits and state education benefits.</p></li><li><p><strong>New Hampshire</strong>: Offers tax exemptions for veterans with adapted homes.</p></li><li><p><strong>Virginia</strong>: Exempts up to $15,000 of military pay from state income tax.</p></li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><h3 id="business-resources" tabindex="-1">Business Resources <a class="header-anchor" href="#business-resources" aria-label="Permalink to &quot;Business Resources&quot;">​</a></h3><ul><li><a href="/general/business.html">Chat Archive</a></li></ul><h3 id="education-and-internships" tabindex="-1">Education and Internships <a class="header-anchor" href="#education-and-internships" aria-label="Permalink to &quot;Education and Internships&quot;">​</a></h3><h4 id="service-member" tabindex="-1">Service Member <a class="header-anchor" href="#service-member" aria-label="Permalink to &quot;Service Member&quot;">​</a></h4><ul><li><p>Explore opportunities for further education and internships to bridge the gap between military and civilian careers. &quot;You can spend your last six months doing a skill bridge with industry. &quot;</p></li><li><p>The <strong>DOD SkillBridge Program</strong> offers valuable civilian work experience for service members during their final 180 days of service. However, participation is subject to approval by the service member&#39;s commander, typically an O6 memo for some branches like the Air Force, while others, like the Army, have their approval processes. Eligibility generally requires service members to serve at least 180 continuous days on active duty. Commanders may approve or disapprove participation based on unit mission requirements.</p></li><li><p><strong>Approval Process</strong>: Commanders must authorize participation, considering unit needs. Participants should complete all Transition Assistance Program (TAP) requirements before starting SkillBridge. Each branch may impose additional requirements.</p></li></ul><p>Thought I&#39;d chime in... I&#39;m three months into a six-month Skillbridge with a company not on the approved Skillbridge list. There are ways to legitimately do that with additional paperwork. Something to be aware of is the Skillbridge process is changing. Also worth noting is the following. <a href="https://www.socom.mil/care-coalition/Pages/Career-Transition.aspx" target="_blank" rel="noreferrer">https://www.socom.mil/care-coalition/Pages/Career-Transition.aspx</a> Buried in, there is a SOCOM &quot;Skillbridge&quot;-like program. Within that are companies (five?) certified Military Mentorship Partners who act as headhunters and look to place you in the right environment/organizations for your skill sets/experiences. I hadn&#39;t even heard of the SOCOM program, and I&#39;ve already gone through SFLTAP, my Unit&#39;s equivalent, the Wounded Warrior Foundation, and the GBF. Just goes to show you there are probably opportunities out there where just unaware of</p><ul><li>For more detailed guidelines, see the <a href="https://skillbridge.osd.mil/faq.htm" target="_blank" rel="noreferrer">SkillBridge FAQ page</a></li></ul><h4 id="employer" tabindex="-1">Employer <a class="header-anchor" href="#employer" aria-label="Permalink to &quot;Employer&quot;">​</a></h4><p>Businesses participating in the DOD SkillBridge Program gain access to skilled, highly motivated service members transitioning out of the military. Through this initiative, employers can create tailored training programs that meet their specific workforce needs while benefiting from the Department of Defense covering service members&#39; salaries and benefits during their final 180 days of service. This allows companies to integrate experienced veterans into their workforce at no additional cost. Employers can host training on base or at their facilities, and virtual or remote learning options are available, making it accessible regardless of location. To ensure success, companies should provide clear job training and development programs, aligning with industry demands and offering a high probability of employment for service members upon completion.</p><ul><li>For more information and participation, visit the <a href="https://skillbridge.osd.mil/industry-employers.htm" target="_blank" rel="noreferrer">for Industry page</a>.</li></ul><h3 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to &quot;Practical Tips&quot;">​</a></h3><ul><li><p>To ensure a smooth transition, it is recommended that service members finalize out-processing, terminal leave, and permissive leave plans in advance when participating in SkillBridge.</p></li><li><p>&quot;No restrictions apply for service members with fewer than six years of service, provided their commander approves participation.&quot; Command approval is key in eligibility, and local policies might vary.</p></li></ul><h3 id="practical-tips-1" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips-1" aria-label="Permalink to &quot;Practical Tips&quot;">​</a></h3><ul><li><p><strong>Practice Interviews</strong>: Apply for jobs at companies you’re less interested in to refine your interviewing and negotiation skills.</p></li><li><p><strong>Negotiating Civilian Jobs</strong>: Learn to anchor your salary expectations high. Try to avoid giving the first number in salary discussions.</p></li></ul><h3 id="financial-planning" tabindex="-1">Financial Planning <a class="header-anchor" href="#financial-planning" aria-label="Permalink to &quot;Financial Planning&quot;">​</a></h3><ul><li><strong>Maximize Savings</strong>: Live frugally in the early stages of your new career to maximize savings and investments.</li></ul><p>[Writing]</p>',50)])])}const m=i(t,[["render",o]]);export{u as __pageData,m as default};
